pub fn array_sum(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x + y)
     .collect()
}

